#!/usr/bin/env bash
# One-command BAH calendar-year rollover for pcsvector.com /bah/ pages. UNOFFICIAL / PERSONAL.
# Usage: run_bah_year.sh <NEW_YEAR> <new_ascii (zip or dir)> <prev_ascii (zip or dir)> [--dry-run]
#   Clones main fresh, runs rollover.py, check_rollover.py (number diff, home sha256), browser check, then pushes branch
#   bah-<YEAR>-rollover and opens a PR into main for Zak's review. NEVER merges. NEVER touches index.html (verified by sha256).
#   --dry-run (stand-in data): branch dryrun/bah-<YEAR>-standin-<stamp>, DRAFT PR titled "DRY RUN - DO NOT MERGE", then closed automatically.
#   Env: HOME_SHA (expected home sha256; default = current main's), CHECKED ("DD Mon YYYY"), TODAY (YYYY-MM-DD), REPO (owner/name), KEEP=1 to keep PR open.
set -euo pipefail
NY=$1; NEW=$2; PREV=$3; DRY=${4:-}
HERE=$(cd "$(dirname "$0")" && pwd); REPO=${REPO:-cortanadaker-a11y/pcsvector-seo}
CHECKED=${CHECKED:-$(date '+%-d %b %Y')}; TODAY=${TODAY:-$(date +%F)}; STAMP=$(date +%Y%m%d-%H%M%S)
W=$(mktemp -d /tmp/bahroll.XXXX); echo "work dir $W"
prep(){ if [[ -d $1 ]]; then echo "$1"; else mkdir -p "$W/$2" && unzip -q -o "$1" -d "$W/$2" && dirname "$(find "$W/$2" -name 'bahw[0-9][0-9].txt' | head -1)"; fi; }
ND=$(prep "$NEW" new); PD=$(prep "$PREV" prev)
YY=${NY:2:2}; PY=$((NY-1)); PYY=${PY:2:2}
if [[ $DRY != --dry-run ]]; then
  ls "$ND/bahw$YY.txt" "$ND/bahwo$YY.txt" >/dev/null || { echo "new ASCII must contain bahw$YY.txt/bahwo$YY.txt"; exit 2; }
  ls "$PD/bahw$PYY.txt" "$PD/bahwo$PYY.txt" >/dev/null || { echo "prev ASCII must contain bahw$PYY.txt/bahwo$PYY.txt"; exit 2; }
fi
git clone -q "https://github.com/$REPO" "$W/site"; cd "$W/site"; git checkout -q main
HOME_SHA=${HOME_SHA:-$(sha256sum index.html | cut -d' ' -f1)}; echo "home sha256 before: $HOME_SHA"
EXP=--expect-prev; [[ $DRY == --dry-run ]] && EXP=
python3 "$HERE/rollover.py" . "$ND" "$PD" "$NY" "$CHECKED" "$TODAY" $EXP | tee "$W/rollover.log"
python3 "$HERE/check_rollover.py" . "$ND" "$PD" "$NY" "$CHECKED" "$TODAY" "$HOME_SHA" "$W/check_rollover.log" | tee "$W/check.out"
[[ $(sha256sum index.html | cut -d' ' -f1) == "$HOME_SHA" ]] || { echo "HOME CHANGED - abort"; exit 3; }
PORT=$((8800 + RANDOM % 900)); python3 -m http.server $PORT --bind 127.0.0.1 >/dev/null 2>&1 & SRV=$!; trap 'kill $SRV 2>/dev/null || true' EXIT; sleep 1
SL=$(ls -d bah/*/ | xargs -n1 basename | paste -sd,)
node "$HERE/rollover_browser.cjs" "http://127.0.0.1:$PORT" "$NY" "$SL" | tee "$W/browser.out"
git diff --stat | tail -1 | tee "$W/diffstat.out"
if [[ $DRY == --dry-run ]]; then BR="dryrun/bah-$NY-standin-$STAMP"; TITLE="DRY RUN - DO NOT MERGE: BAH $NY rollover (stand-in data)"; else BR="bah-$NY-rollover"; TITLE="BAH $NY: all /bah/ pages to DTMO $NY rates + $NY vs $PY table"; fi
git checkout -q -b "$BR"; git add bah sitemap.xml; git -c user.name="cortanadaker-a11y" -c user.email="cortanadaker-a11y@users.noreply.github.com" commit -q -m "$TITLE"
git push -q origin "$BR"
BODY="$W/pr_body.md"; { echo "UNOFFICIAL / PERSONAL. Generated by _builder/bah_yearly/run_bah_year.sh."; echo; echo "- New-year ASCII: \`$NEW\`; prev-year ASCII: \`$PREV\`"; echo "- Number diff: $(tail -1 "$W/check.out" | grep -o 'checks.*' || cat "$W/check.out" | grep checks)"; echo "- Browser: $(grep -o 'pages.*' "$W/browser.out")"; echo "- Home index.html sha256 unchanged: $HOME_SHA"; echo "- Diff: $(cat "$W/diffstat.out")"; echo; echo "Not merged by the pipeline. Zak reviews and merges."; [[ $DRY == --dry-run ]] && echo && echo "**DRY RUN with stand-in data. Do not merge. Closed automatically.**"; } > "$BODY"
if [[ $DRY == --dry-run ]]; then URL=$(gh pr create -R "$REPO" --base main --head "$BR" --draft --title "$TITLE" --body-file "$BODY"); echo "PR $URL"; [[ ${KEEP:-} == 1 ]] || gh pr close -R "$REPO" "$URL" -c "Dry run complete; closed by pipeline (not merged)."
else URL=$(gh pr create -R "$REPO" --base main --head "$BR" --title "$TITLE" --body-file "$BODY"); echo "PR $URL (awaiting Zak's review/merge)"; fi
echo "logs in $W"
